<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
const status=ref<{mfa_enabled:boolean;mfa_required?:boolean;recovery_codes_remaining?:number;pending_email:string|null;google_linked:boolean;local_inbox:boolean}|null>(null);const sessions=ref<{id:number;name:string;last_used_at:string;expires_at:string}[]>([])
const codes=ref<string[]>([]);
const error=ref('');const notice=ref('');const busy=ref(false);const open=ref(false);const action=ref('');const form=ref({current_password:'',password:'',password_confirmation:'',email:'',mfa_code:''});const secret=ref('');const sessionId=ref(0);const providers=ref(false)
watch(open,v=>{if(!v){codes.value=[];secret.value='';form.value.current_password='';form.value.mfa_code=''}})
async function load(){error.value='';try{status.value=await request('/security');sessions.value=(await request<{data:typeof sessions.value}>('/security/sessions')).data;providers.value=(await request<{google_enabled:boolean}>('/auth/providers')).google_enabled}catch(e){error.value=(e as Error).message}}
function edit(type:string,id=0){action.value=type;sessionId.value=id;error.value='';secret.value='';codes.value=[];form.value={current_password:'',password:'',password_confirmation:'',email:'',mfa_code:''};open.value=true}
async function save(){busy.value=true;error.value='';try{
 if(action.value==='codes-show'){codes.value=[];open.value=false;await load();return}
 else if(action.value==='recovery'){codes.value=(await request<{codes:string[]}>('/security/mfa/recovery-codes','POST',form.value)).codes;form.value.current_password='';form.value.mfa_code='';action.value='codes-show';return}
 else if(action.value==='verify'){await request('/auth/email/request','POST');notice.value='Vérification préparée. Consultez l’état dans Notifications.'}
 else if(action.value==='session'){await request('/security/sessions/'+sessionId.value,'DELETE');notice.value='Session révoquée.'}
 else if(action.value==='mfa-setup'){const d=await request<{secret:string}>('/security/mfa/setup','POST',form.value);secret.value=d.secret;action.value='mfa-confirm';return}
 else if(action.value==='google-link'){const d=await request<{url:string}>('/auth/google/start','POST',{...form.value,link:true});window.location.assign(d.url);return}
 else {const path=action.value==='password'?'/security/password':action.value==='email'?'/security/email':action.value==='mfa-confirm'?'/security/mfa/confirm':action.value==='google-unlink'?'/security/google':'/security/mfa';await request(path,action.value==='mfa-disable'||action.value==='google-unlink'?'DELETE':'POST',form.value);if(action.value!=='email'){sessionStorage.clear();window.location.assign('/login');return}notice.value='Nouvelle adresse en attente de vérification.'}
 open.value=false;await load()
 }catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
const titles:Record<string,string>={recovery:'Renouveler les codes de secours','codes-show':'Conservez vos codes hors de votre compte',password:'Changer le mot de passe',email:'Changer l’adresse email','mfa-setup':'Configurer MFA','mfa-confirm':'Confirmer MFA','mfa-disable':'Désactiver MFA',verify:'Demander un lien de vérification',session:'Révoquer cette session ?','google-link':'Associer Google','google-unlink':'Dissocier Google'}
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · COMPTE PERSONNEL</p><h1>Sécurité & MFA</h1><p class="page-subtitle">Vérification de l’identité, authentification et sessions.</p></div></div><div v-if="demoMode" class="panel form-body"><h2>Sécurité réelle disponible en mode API</h2><p>La démo ne simule ni vérification d’identité ni activation MFA. Utilisez l’aperçu connecté.</p></div><template v-else><p v-if="status?.mfa_required&&!status?.mfa_enabled" role="alert" class="alert">MFA obligatoire : configurez votre application TOTP pour débloquer vos fonctions. Vous pouvez toujours gérer votre sécurité et vous déconnecter.</p><p v-if="status?.mfa_required&&status?.mfa_enabled" class="review-note">MFA obligatoire actif. Conservez vos codes de secours hors de votre compte.</p><p v-if="error&&!open" role="alert" class="alert error">{{error}}</p><p v-if="notice" role="status" class="alert success">{{notice}}</p><div class="panel"><div class="panel-heading"><h2>Identifiants et vérification</h2></div><div class="form-body"><p v-if="status?.pending_email" class="review-note">Changement d’adresse en attente : {{status.pending_email}}</p><div class="module-links"><button class="button secondary" @click="edit('verify')">Vérifier mon email</button><button class="button secondary" @click="edit('email')">Changer l’email</button><button class="button secondary" @click="edit('password')">Changer le mot de passe</button><RouterLink to="/notifications" class="button secondary">Notifications & livraison</RouterLink></div></div></div><div class="panel overview-recent"><div class="panel-heading"><div><h2>Authentification à deux facteurs</h2><p class="page-subtitle">Application TOTP compatible · {{status?.mfa_enabled?'Activée':'Non activée'}}</p></div><button v-if="!status?.mfa_enabled||!status?.mfa_required" class="button primary" @click="edit(status?.mfa_enabled?'mfa-disable':'mfa-setup')">{{status?.mfa_enabled?'Désactiver':'Configurer MFA'}}</button></div><div class="form-body"><p class="module-disclaimer">Le code change toutes les 30 secondes. Un code accepté ne peut pas être rejoué. Activation, désactivation et changement de mot de passe révoquent les sessions. Les codes de secours à usage unique permettent de vous connecter si votre application est perdue. Sans application ni code, aucune réinitialisation MFA automatique n’est proposée. MFA obligatoire pour les administrateurs plateforme, les administrateurs d’officine et les coordinateurs. La désactivation est interdite tant que vous exercez ces fonctions.</p><button v-if="status?.mfa_enabled" class="button secondary" @click="edit('recovery')">Renouveler les codes de secours</button><p v-if="status?.mfa_enabled" class="page-subtitle">{{status.recovery_codes_remaining||0}} code(s) de secours restant(s).</p></div></div><div class="panel overview-recent"><div class="panel-heading"><h2>Connexion Google</h2><button v-if="providers||status?.google_linked" class="button secondary" @click="edit(status?.google_linked?'google-unlink':'google-link')">{{status?.google_linked?'Dissocier Google':'Associer Google'}}</button><span v-else class="module-chip">Configuration requise</span></div><div class="form-body"><p class="page-subtitle">Aucune association automatique par simple égalité d’email. L’association d’un compte existant requiert votre authentification et une vérification du mot de passe.</p></div></div><div class="panel overview-recent"><div class="panel-heading"><h2>Mes sessions</h2><button class="button secondary" @click="load">Actualiser</button></div><div class="table-scroll"><table><thead><tr><th>SESSION</th><th>DERNIÈRE UTILISATION</th><th>EXPIRATION</th><th>ACTION</th></tr></thead><tbody><tr v-for="s in sessions" :key="s.id"><td>#{{s.id}} · {{s.name}}</td><td>{{s.last_used_at||'—'}}</td><td>{{s.expires_at}} UTC</td><td><button class="button secondary small" @click="edit('session',s.id)">Révoquer</button></td></tr></tbody></table></div></div></template>
<AppModal v-model="open" :title="titles[action]||'Sécurité'" :busy="busy"><form id="security-form" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><template v-if="!['session','verify','mfa-confirm','codes-show'].includes(action)"><label>Mot de passe actuel<input v-model="form.current_password" type="password" autocomplete="current-password" required maxlength="512"/></label></template><template v-if="action==='password'"><label>Nouveau mot de passe<input v-model="form.password" type="password" autocomplete="new-password" required minlength="12" maxlength="128"/></label><label>Confirmation<input v-model="form.password_confirmation" type="password" autocomplete="new-password" required minlength="12" maxlength="128"/></label></template><label v-if="action==='email'">Nouvelle adresse<input v-model="form.email" type="email" required maxlength="254"/></label><template v-if="action==='mfa-confirm'"><p>Ajoutez cette clé dans votre application d’authentification, puis saisissez son code. Cette clé n’est pas enregistrée dans le navigateur.</p><code class="mfa-secret">{{secret}}</code></template><label v-if="action==='mfa-confirm'||(status?.mfa_enabled&&!['session','verify','codes-show'].includes(action))">Code MFA ou code de secours<input v-model="form.mfa_code" autocomplete="one-time-code" :pattern="action==='mfa-confirm'?'[0-9]{6}':'([0-9]{6}|[a-f0-9]{32})'" maxlength="32" required/></label><template v-if="action==='codes-show'"><p>Ces dix codes ne seront affichés qu’une fois. Chaque code remplace un code MFA une seule fois et nécessite toujours votre mot de passe. Les anciens codes sont invalides.</p><code v-for="c in codes" :key="c" class="mfa-secret">{{c}}</code></template><p v-if="action==='session'">Révoquer la session courante vous demandera de vous reconnecter à la prochaine requête.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false;secret='';codes=[]">Annuler</button><button class="button primary" :disabled="busy" form="security-form" type="submit">{{busy?'Traitement…':'Confirmer'}}</button></template></AppModal></section></template>
